12	/** The due figures of claims, and the due-totals of people, at the rates on a sheet. */
13	@Service
14	public class Dues {
15	
16	    private final RateRepository rates;
17	    private final SheetService sheets;
18	
19	    public Dues(RateRepository rates, SheetService sheets) {
20	        this.rates = rates;
21	        this.sheets = sheets;
22	    }
23	
24	    /** The due figure a claim shows and totals: the one fixed when it was settled, or else the one
25	     *  its person's last statement bound it to, or else its live due; null when there is none. */
26	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
27	        if (claim.getSettledDue() != null) {
28	            return claim.getSettledDue();
29	        }
30	        if (claim.isStated() && claim.getStatedDue() != null) {
31	            return claim.getStatedDue();
32	        }
33	        return due(sheetId, person, claim);
34	    }
35	
36	    /** Whether a claim of the person counts in the live totals: it counts, and it is not an open
37	     *  claim of a person on hold. */
38	    public static boolean countsLive(Person person, Claim claim) {
39	        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
40	    }
41	
42	    /** The claims of a person that count in the live totals. */
43	    public static List<Claim> live(Person person, List<Claim> theirs) {
44	        return theirs.stream().filter(c -> countsLive(person, c)).toList();
45	    }
46	
47	    /** A person's due-total: the sum of the figures of their claims that count; null (n/a) when
48	     *  their grade has no rate on the sheet's today and no counting claim keeps a fixed figure. */
49	    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
50	        List<Claim> counted = theirs.stream().filter(c -> c.getStatus().counts()).toList();
51	        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheets.today(sheetId)).isPresent();
52	        boolean fixed = counted.stream().anyMatch(c -> c.getSettledDue() != null
53	                || (c.isStated() && c.getStatedDue() != null));
54	        if (!rated && !fixed) {
55	            return null;
56	        }
57	        return counted.stream().map(c -> figure(sheetId, person, c)).filter(d -> d != null)
58	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
59	    }
60	
61	    /** A claim's live due at the rate for the person's grade in force on the claim's date: amount
62	     *  times pct divided by 100, rounded half to even to two decimals, and at least the sheet's
63	     *  floor; null when no rate applies on that date. */
64	    private BigDecimal due(String sheetId, Person person, Claim claim) {
65	        BigDecimal floor = sheets.floor(sheetId);
66	        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
67	                .map(Rate::getPct)
68	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
69	                .map(due -> due.max(floor))
70	                .orElse(null);
71	    }
72	}
