229	package net.officefloor.hq.app.claim;
230	
231	import java.math.BigDecimal;
232	import java.time.LocalDate;
233	import java.util.List;
234	import net.officefloor.hq.app.Audit;
235	import net.officefloor.hq.app.period.PeriodRepository;
236	import net.officefloor.hq.app.person.Person;
237	import net.officefloor.hq.app.person.PersonRepository;
238	import net.officefloor.hq.app.role.RoleService;
239	import net.officefloor.hq.app.role.SheetRole;
240	import net.officefloor.hq.app.rollup.Rollup;
241	import net.officefloor.hq.app.sheet.SheetService;
242	import org.springframework.http.HttpStatus;
243	import org.springframework.stereotype.Service;
244	import org.springframework.transaction.annotation.Transactional;
245	import org.springframework.web.server.ResponseStatusException;
246	
247	/** The claims people make on a sheet. */
248	@Service
249	public class ClaimService {
250	
251	    private final ClaimRepository claims;
252	    private final PersonRepository people;
253	    private final Dues dues;
254	    private final SheetService sheets;
255	    private final Rollup rollup;
256	    private final PeriodRepository periods;
257	    private final RoleService roles;
258	    private final Audit audit;
259	
260	    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
261	            Rollup rollup, PeriodRepository periods, RoleService roles, Audit audit) {
262	        this.claims = claims;
263	        this.people = people;
264	        this.dues = dues;
265	        this.sheets = sheets;
266	        this.rollup = rollup;
267	        this.periods = periods;
268	        this.roles = roles;
269	        this.audit = audit;
270	    }
271	
272	    /** The claims on the sheet, newest first. */
273	    @Transactional(readOnly = true)
274	    public List<Claim> list(String sheetId) {
275	        return claims.findBySheetIdOrderByIdDesc(sheetId);
276	    }
277	
278	    /** Add a claim for a person; a date left out takes the sheet's today. Refused when the date falls
279	     *  inside a closed period, or after the person's retirement day. */
280	    @Transactional
281	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
282	        LocalDate on = date != null ? date : sheets.today(sheetId);
283	        refuseClosed(sheetId, on);
284	        refuseRetired(person(sheetId, personId), on);
285	        return rollup.tracking(sheetId, user, () -> {
286	            Person person = person(sheetId, personId);
287	            Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount, on, note));
288	            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim));
289	            return claim;
290	        });
291	    }
292	
293	    /** Change a draft claim's amount, date and note; a date left out takes the sheet's today. Refused
294	     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
295	     *  when the claim's date, or the new one, falls inside a closed period, and when the new one is
296	     *  after the person's retirement day. */
297	    @Transactional
298	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
299	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
300	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
301	        if (claim.getStatus() != ClaimStatus.DRAFT) {
302	            throw new ResponseStatusException(HttpStatus.CONFLICT,
303	                    "A " + claim.getStatus() + " claim cannot be edited");
304	        }
305	        LocalDate on = date != null ? date : sheets.today(sheetId);
306	        refuseClosed(sheetId, claim.getDate());
307	        refuseClosed(sheetId, on);
308	        refuseRetired(person(sheetId, claim.getPersonId()), on);
309	        return rollup.tracking(sheetId, user, () -> {
310	            claim.setAmount(amount);
311	            claim.setDate(on);
312	            claim.setNote(note);
313	            Claim saved = claims.saveAndFlush(claim);
314	            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
315	            return saved;
316	        });
317	    }
318	
319	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
320	     *  is settling a claim by the user who opened it, settling by a clerk a claim whose due is above
321	     *  the sheet's clerk limit, and any change to a claim dated inside a closed period. */
322	    @Transactional
323	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
324	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId)
325	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
326	        refuseClosed(sheetId, claim.getDate());
327	        if (!claim.getStatus().canBecome(to)) {
328	            throw new ResponseStatusException(HttpStatus.CONFLICT,
329	                    "A " + claim.getStatus() + " claim cannot become " + to);
330	        }
331	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
332	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
333	                    "The user who opened a claim cannot settle it");
334	        }
335	        if (to == ClaimStatus.SETTLED) {
336	            refuseOverClerkLimit(sheetId, user, claim);
337	        }
338	        return rollup.tracking(sheetId, user, () -> {
339	            // A void claim keeps the number it had (never reused).
340	            claim.setStatus(to);
341	            if (to == ClaimStatus.OPEN) {
342	                claim.setNumber(sheets.nextClaimNumber(sheetId));
343	                claim.setOpenedBy(user);
344	            }
345	            Person person = person(sheetId, claim.getPersonId());
346	            if (to == ClaimStatus.SETTLED) {
347	                // Settling fixes the due at what it is now (the figure a statement bound it to, if any);
348	                // later changes to rates do not alter it.
349	                claim.setSettledDue(dues.figure(sheetId, person, claim));
350	            }
351	            Claim saved = claims.saveAndFlush(claim);
352	            String event = switch (to) {
353	                case OPEN -> "CLAIM_OPENED";
354	                case SETTLED -> "CLAIM_SETTLED";
355	                case VOID -> "CLAIM_VOIDED";
356	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
357	            };
358	            String line = record(event, sheetId, user, person, saved);
359	            if (to == ClaimStatus.SETTLED) {
360	                line += " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString());
361	            }
362	            audit.recordOnCommit(line);
363	            return saved;
364	        });
365	    }
366	
367	    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
368	    private void refuseClosed(String sheetId, LocalDate day) {
369	        if (periods.closedOn(sheetId, day)) {
370	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
371	        }
372	    }
373	
374	    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a claim with no
375	     *  due (n/a) is within any limit, and a steward settles anything. */
376	    private void refuseOverClerkLimit(String sheetId, String user, Claim claim) {
377	        BigDecimal limit = sheets.clerkLimit(sheetId);
378	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
379	            return;
380	        }
381	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
382	        if (due != null && due.compareTo(limit) > 0) {
383	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
384	                    "A clerk cannot settle a claim whose due is above the clerk limit");
385	        }
386	    }
387	
388	    /** Refuse a claim of the person dated after the day they are retired from. */
389	    private static void refuseRetired(Person person, LocalDate day) {
390	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
391	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
392	                    "A claim cannot be dated after the person's retirement");
393	        }
394	    }
395	
396	    private Person person(String sheetId, long personId) {
397	        return people.findByIdAndSheetId(personId, sheetId)
398	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
399	    }
400	
401	    /** An audit record about a claim; one that has a number carries it at the end. */
402	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
403	        Integer number = claim.getNumber();
404	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
405	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
406	                + (number != null ? " number=" + number : "");
407	    }
408	}
