659	package net.officefloor.hq.app.sheet;
660	
661	import java.math.BigDecimal;
662	import java.time.LocalDate;
663	import net.officefloor.hq.app.Audit;
664	import net.officefloor.hq.app.rollup.Rollup;
665	import org.springframework.context.annotation.Lazy;
666	import org.springframework.stereotype.Service;
667	import org.springframework.transaction.annotation.Transactional;
668	
669	/** Loads sheets by id; a sheet that was never loaded before starts empty. */
670	@Service
671	public class SheetService {
672	
673	    private final SheetRepository sheets;
674	    /** Lazy: the rollup reads the sheet's today through this service. */
675	    private final Rollup rollup;
676	    private final Audit audit;
677	
678	    public SheetService(SheetRepository sheets, @Lazy Rollup rollup, Audit audit) {
679	        this.sheets = sheets;
680	        this.rollup = rollup;
681	        this.audit = audit;
682	    }
683	
684	    /** The sheet with this id, created empty the first time it is loaded, its today the real date. */
685	    @Transactional
686	    public synchronized Sheet load(String id, String user) {
687	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, user, LocalDate.now())));
688	    }
689	
690	    /** The sheet's today: the date every date-dependent decision and default date on it uses. */
691	    @Transactional(readOnly = true)
692	    public LocalDate today(String id) {
693	        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
694	    }
695	
696	    /** The next claim number on the sheet: 1 for its first opened claim, then 2, and so on. */
697	    @Transactional
698	    public int nextClaimNumber(String id) {
699	        if (sheets.advanceClaimNumber(id) != 1) {
700	            throw new IllegalStateException("No sheet " + id);
701	        }
702	        return sheets.lastClaimNumber(id);
703	    }
704	
705	    /** Change the sheet's today; the figures it moves are recorded, with no record of its own. */
706	    @Transactional
707	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
708	        Sheet sheet = load(id, user);
709	        return rollup.tracking(id, user, () -> {
710	            sheet.setToday(today);
711	            return sheets.saveAndFlush(sheet);
712	        });
713	    }
714	
715	    /** The most due a clerk may settle on a claim on the sheet; null when there is no limit. */
716	    @Transactional(readOnly = true)
717	    public BigDecimal clerkLimit(String id) {
718	        return sheets.findById(id).map(Sheet::getClerkLimit).orElse(null);
719	    }
720	
721	    /** Change the sheet's clerk limit (null: no limit); recorded even when it is unchanged. */
722	    @Transactional
723	    public synchronized Sheet setClerkLimit(String id, String user, BigDecimal limit) {
724	        Sheet sheet = load(id, user);
725	        sheet.setClerkLimit(limit);
726	        Sheet saved = sheets.saveAndFlush(sheet);
727	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=clerk-limit value="
728	                + (limit == null ? "" : limit.setScale(2).toPlainString()));
729	        return saved;
730	    }
731	
732	    /** The least live due a claim on the sheet has; 1.00 for a sheet never loaded. */
733	    @Transactional(readOnly = true)
734	    public BigDecimal floor(String id) {
735	        return sheets.findById(id).map(Sheet::getFloor).orElse(new BigDecimal("1.00"));
736	    }
737	
738	    /** Change the sheet's floor; recorded even when it is unchanged, then the figures it moves. */
739	    @Transactional
740	    public synchronized Sheet setFloor(String id, String user, BigDecimal floor) {
741	        Sheet sheet = load(id, user);
742	        return rollup.tracking(id, user, () -> {
743	            sheet.setFloor(floor);
744	            Sheet saved = sheets.saveAndFlush(sheet);
745	            audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=floor value="
746	                    + floor.setScale(2).toPlainString());
747	            return saved;
748	        });
749	    }
750	
751	    /** The days after its date a claim on the sheet is due by; 14 for a sheet never loaded. */
752	    @Transactional(readOnly = true)
753	    public int terms(String id) {
754	        return sheets.findById(id).map(Sheet::getTerms).orElse(14);
755	    }
756	
757	    /** Change the sheet's terms; recorded even when they are unchanged. They move no rolled-up figure. */
758	    @Transactional
759	    public synchronized Sheet setTerms(String id, String user, int terms) {
760	        Sheet sheet = load(id, user);
761	        sheet.setTerms(terms);
762	        Sheet saved = sheets.saveAndFlush(sheet);
763	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms value=" + terms);
764	        return saved;
