960	/**
961	 * The figures a sheet rolls up to: what each person has claimed and their due-total, and the
962	 * sheet's totals of both. A change made through {@link #tracking} is followed in the audit by one
963	 * ROLLUP line per person whose figures it moved (in the order they were added), then a TOTALS line
964	 * when the sheet's totals moved.
965	 */
966	@Service
967	public class Rollup {
968	
969	    /** A person's figures as two-decimal text; a due-total of n/a is "n/a". */
970	    private record Figures(String name, String claimed, String dueTotal) {
971	        boolean sameAs(Figures other) {
972	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
973	        }
974	    }
975	
976	    /** The figures of a sheet: each person's by id in the order they were added, and the totals. */
977	    private record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
978	    }
979	
980	    private final PersonRepository people;
981	    private final ClaimRepository claims;
982	    private final Dues dues;
983	    private final Audit audit;
984	
985	    public Rollup(PersonRepository people, ClaimRepository claims, Dues dues, Audit audit) {
986	        this.people = people;
987	        this.claims = claims;
988	        this.dues = dues;
989	        this.audit = audit;
990	    }
991	
992	    /** Make a change on the sheet, then record in the audit, after the change's own records, the
993	     *  figures it moved. A change that is refused records nothing. */
994	    @Transactional(propagation = Propagation.MANDATORY)
995	    public <T> T tracking(String sheetId, String user, Supplier<T> change) {
996	        Snapshot before = snapshot(sheetId);
997	        T result = change.get();
998	        Snapshot after = snapshot(sheetId);
999	        String prefix = " sheet=" + sheetId + " by=" + user;
1000	        after.people().forEach((id, figures) -> {
1001	            if (!figures.sameAs(before.people().get(id))) {
1002	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
1003	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal());
1004	            }
1005	        });
1006	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
1007	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
1008	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
1009	                    + " due-total=" + after.dueTotal());
1010	        }
1011	        return result;
1012	    }
1013	
1014	    private Snapshot snapshot(String sheetId) {
1015	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
1016	                .collect(Collectors.groupingBy(Claim::getPersonId));
1017	        Map<Long, Figures> figures = new LinkedHashMap<>();
1018	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
1019	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
1020	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
1021	            List<Claim> theirs = Dues.live(person, byPerson.getOrDefault(person.getId(), List.of()));
1022	            BigDecimal claimed = theirs.stream().map(Claim::getAmount)
1023	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
1024	            BigDecimal due = dues.dueTotal(sheetId, person, theirs);
1025	            claimedTotal = claimedTotal.add(claimed);
1026	            if (due != null) {
1027	                dueTotal = dueTotal.add(due);
1028	            }
1029	            figures.put(person.getId(), new Figures(person.getName(), text(claimed),
1030	                    due == null ? "n/a" : text(due)));
1031	        }
1032	        return new Snapshot(figures, text(claimedTotal), text(dueTotal));
1033	    }
1034	
1035	    private static String text(BigDecimal value) {
1036	        return value.setScale(2).toPlainString();
1037	    }
1038	}
