8	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
9	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
10	
11	/** A change of status a claim can be asked for. */
12	export type ClaimAction = 'open' | 'settle' | 'void';
13	
14	/** Whether a claim at this status counts toward claimed, due-total and every total. */
15	export function counts(c: Claim): boolean {
16	  return c.status === 'OPEN' || c.status === 'SETTLED';
17	}
18	
19	/** Whether a claim counts in the live totals: it counts, and it is not an open claim of a person
20	 *  on hold. */
21	export function countsLive(c: Claim, held: boolean): boolean {
22	  return counts(c) && !(held && c.status === 'OPEN');
23	}
