25	export interface Claim {
26	  id: number;
27	  personId: number;
28	  /** The amount as text with two decimals. */
29	  amount: string;
30	  date: string;
31	  note: string;
32	  status: ClaimStatus;
33	  /** The claim's number on the sheet, given when it is opened; null for a draft or a void claim. */
34	  number: number | null;
35	  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
36	   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
37	  settledDue: string | null;
38	  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
39	  openedBy: string | null;
40	  /** Whether its person's last statement bound it to the due it had then. */
41	  stated: boolean;
42	  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
43	   *  or was bound while it had no due (its due then stays live). */
44	  statedDue: string | null;
45	}
