62	/** An amount with up to two decimals, 0.00 or more. */
63	export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;
64	
65	/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
66	export function sumAmounts(amounts: string[]): string {
67	  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
68	  return (cents / 100).toFixed(2);
69	}
70	
71	/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
72	 *  statement. */
73	export function fixed(c: Claim): boolean {
74	  return c.settledDue !== null || (c.stated && c.statedDue !== null);
75	}
76	
77	/** A claim's due figure: the one fixed when it was settled, or else the one its person's last
78	 *  statement bound it to, or else its live due at its person's grade's rate in force on the
79	 *  claim's date, at least the sheet's floor; null when there is none. */
80	export function claimDue(c: Claim, rates: Rate[], grade: Grade, floor: string): string | null {
81	  const live = due(c.amount, pctOn(rates, grade, c.date));
82	  return c.settledDue ?? (c.stated ? c.statedDue : null) ?? (live === null ? null : atLeast(live, floor));
83	}
