85	/** The day (yyyy-mm-dd) a claim is due by: its date plus the sheet's terms in days. */
86	export function dueBy(c: Claim, terms: number): string {
87	  const [y, m, d] = c.date.split('-').map(Number);
88	  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
89	}
90	
91	/** Whether a claim is overdue: it is open and its due-by is before the sheet's today. */
92	export function overdue(c: Claim, terms: number, today: string | null): boolean {
93	  return c.status === 'OPEN' && today !== null && dueBy(c, terms) < today;
94	}
