97	@Injectable({ providedIn: 'root' })
98	export class Claims {
99	  private readonly http = inject(HttpClient);
100	  private readonly session = inject(Session);
101	
102	  /** Every claim on the sheet, newest first. */
103	  list(sheetId: string): Promise<Claim[]> {
104	    return firstValueFrom(this.http.get<Claim[]>(`${this.url(sheetId)}/claims`));
105	  }
106	
107	  add(personId: number, form: ClaimForm): Promise<Claim> {
108	    const { sheetId, user } = this.active();
109	    return firstValueFrom(
110	      this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, { headers: { 'X-User': user } }),
111	    );
112	  }
113	
114	  /** Add a draft claim of the amount, dated the sheet's today, for the person of the name, who is
115	   *  added at grade A first when the name is not on the sheet. */
116	  quickAdd(name: string, amount: string): Promise<QuickAdded> {
117	    const { sheetId, user } = this.active();
118	    return firstValueFrom(
119	      this.http.post<QuickAdded>(`${this.url(sheetId)}/quick-add`, { name, amount }, { headers: { 'X-User': user } }),
120	    );
121	  }
122	
123	  edit(id: number, form: ClaimForm): Promise<Claim> {
124	    const { sheetId, user } = this.active();
125	    return firstValueFrom(
126	      this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: { 'X-User': user } }),
127	    );
128	  }
129	
130	  /** Ask for a change of the claim's status; refused (409) when its status does not allow it. */
131	  act(id: number, action: ClaimAction): Promise<Claim> {
132	    const { sheetId, user } = this.active();
133	    return firstValueFrom(
134	      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: { 'X-User': user } }),
135	    );
136	  }
137	
138	  private url(sheetId: string): string {
139	    return `/api/sheets/${encodeURIComponent(sheetId)}`;
140	  }
141	
142	  private active(): { sheetId: string; user: string } {
143	    const sheetId = this.session.sheetId();
144	    const user = this.session.user();
145	    if (!sheetId || !user) throw new Error('no sheet loaded');
146	    return { sheetId, user };
147	  }
148	}
