import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade, Person } from './people';
import { Rate, atLeast, due, pctOn } from './rates';
import { Session } from './session';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A change of status a claim can be asked for. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Whether a claim at this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

/** Whether a claim counts in the live totals: it counts, and it is not an open claim of a person
 *  on hold. */
export function countsLive(c: Claim, held: boolean): boolean {
  return counts(c) && !(held && c.status === 'OPEN');
}

export interface Claim {
  id: number;
  personId: number;
  /** The amount as text with two decimals. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened; null for a draft or a void claim. */
  number: number | null;
  /** The due fixed when the claim was settled, as text with two decimals; null when it is not
   *  settled, or was settled while its person's grade had no rate (its due then stays live). */
  settledDue: string | null;
  /** Who opened the claim; null when it was never opened. That user cannot settle it. */
  openedBy: string | null;
  /** Whether its person's last statement bound it to the due it had then. */
  stated: boolean;
  /** The due the last statement bound it to, as text with two decimals; null when it is unbound,
   *  or was bound while it had no due (its due then stays live). */
  statedDue: string | null;
}

export interface ClaimForm {
  amount: string;
  /** yyyy-mm-dd, or null for the sheet's today. */
  date: string | null;
  note: string;
}

/** What a quick-add made: the person the claim is for (added when the name was not on the sheet)
 *  and the draft claim. */
export interface QuickAdded {
  person: Person;
  personAdded: boolean;
  claim: Claim;
}

/** An amount with up to two decimals, 0.00 or more. */
export const AMOUNT = /^\d{1,12}(\.\d{1,2})?$/;

/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
export function sumAmounts(amounts: string[]): string {
  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
 *  statement. */
export function fixed(c: Claim): boolean {
  return c.settledDue !== null || (c.stated && c.statedDue !== null);
}

/** A claim's due figure: the one fixed when it was settled, or else the one its person's last
 *  statement bound it to, or else its live due at its person's grade's rate in force on the
 *  claim's date, at least the sheet's floor; null when there is none. */
export function claimDue(c: Claim, rates: Rate[], grade: Grade, floor: string): string | null {
  const live = due(c.amount, pctOn(rates, grade, c.date));
  return c.settledDue ?? (c.stated ? c.statedDue : null) ?? (live === null ? null : atLeast(live, floor));
}

/** The day (yyyy-mm-dd) a claim is due by: its date plus the sheet's terms in days. */
export function dueBy(c: Claim, terms: number): string {
  const [y, m, d] = c.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is open and its due-by is before the sheet's today. */
export function overdue(c: Claim, terms: number, today: string | null): boolean {
  return c.status === 'OPEN' && today !== null && dueBy(c, terms) < today;
}

// The claims people make on the active sheet.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Every claim on the sheet, newest first. */
  list(sheetId: string): Promise<Claim[]> {
    return firstValueFrom(this.http.get<Claim[]>(`${this.url(sheetId)}/claims`));
  }

  add(personId: number, form: ClaimForm): Promise<Claim> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, { headers: { 'X-User': user } }),
    );
  }

  /** Add a draft claim of the amount, dated the sheet's today, for the person of the name, who is
   *  added at grade A first when the name is not on the sheet. */
  quickAdd(name: string, amount: string): Promise<QuickAdded> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<QuickAdded>(`${this.url(sheetId)}/quick-add`, { name, amount }, { headers: { 'X-User': user } }),
    );
  }

  edit(id: number, form: ClaimForm): Promise<Claim> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: { 'X-User': user } }),
    );
  }

  /** Ask for a change of the claim's status; refused (409) when its status does not allow it. */
  act(id: number, action: ClaimAction): Promise<Claim> {
    const { sheetId, user } = this.active();
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: { 'X-User': user } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private active(): { sheetId: string; user: string } {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return { sheetId, user };
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Claim, Claims, QuickAdded, claimDue, countsLive, fixed, overdue, sumAmounts } from '../../core/claims';
import { Grade, People, Person } from '../../core/people';
import { Period, Periods, periodOf } from '../../core/periods';
import { Rate, Rates, pctOn } from '../../core/rates';
import { Session } from '../../core/session';
import { SheetSettings } from '../../core/settings';
import { PersonClaims } from '../claims/person-claims';
import { PeriodForm } from '../periods/period-form';
import { RateForm } from '../rates/rate-form';
import { QuickAddBar } from './quick-add-bar';

// The people on the sheet, in the order they were added, and the form that adds a person or,
// once a person's editor is opened, edits them. Each person's row lists their claims and what
// they have claimed and are due at their grade's rate; the sheet's totals add everyone's up.
// Retired people are left out of the list unless "show retired" is on; their claims still count.
// The open claims of a person on hold count in no total; their settled claims still do.
@Component({
  selector: 'app-people-list',
  imports: [ReactiveFormsModule, PersonClaims, RateForm, PeriodForm, QuickAddBar],
  template: `
    <app-rate-form [rates]="rates()" (saved)="rateSaved($event)" />
    <app-period-form [periods]="periods()" [dueTotals]="periodDueTotals()" (saved)="periodSaved($event)" />
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form data-testid="person-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="person-form-name">Name</label>
        <input id="person-form-name" data-testid="person-form-name" formControlName="name" />
        <label for="person-form-grade">Grade</label>
        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="person-form-submit">{{ editing() === null ? 'Add person' : 'Save' }}</button>
        @if (editing() !== null) {
          <button type="button" data-testid="person-form-cancel" (click)="cancel()">Cancel</button>
        }
        @if (error()) {
          <p role="alert" data-testid="person-form-error">{{ error() }}</p>
        }
      </form>
      <app-quick-add-bar (added)="quickAdded($event)" />
      <p>Claimed in total: <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
      <p>Due in total: <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
      <p>Overdue claims: <strong data-testid="rollup-overdue-count">{{ overdueCount() }}</strong></p>
      <p>Overdue in total: <strong data-testid="rollup-overdue-total">{{ overdueTotal() }}</strong></p>
      <label>
        <input type="checkbox" data-testid="show-retired" [checked]="showRetired()"
          (change)="showRetired.set($any($event.target).checked)" />
        Show retired
      </label>
      <table data-testid="people">
        <thead>
          <tr><th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th><th scope="col">Statements</th><th scope="col">Last stated</th><th scope="col">Stated on</th><th scope="col">Retired</th><th scope="col">Retired from</th><th scope="col">On hold</th><th scope="col">Overdue</th><th scope="col">Overdue due</th><th scope="col">Claims</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
        </thead>
        <tbody>
          @for (p of shown(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              <td data-testid="person-claimed">{{ claimed().get(p.id) ?? '0.00' }}</td>
              <td data-testid="person-due-total">{{ dueOf(p) ?? 'n/a' }}</td>
              <td data-testid="person-statement-count">{{ p.statementCount }}</td>
              <td data-testid="person-stated-total">{{ p.statementCount > 0 ? (p.statedTotal ?? 'n/a') : '' }}</td>
              <td data-testid="person-statement-date">{{ p.statementDate ?? '' }}</td>
              <td data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</td>
              <td data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</td>
              <td data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</td>
              <td data-testid="person-overdue-count">{{ overdueOf(p).length }}</td>
              <td data-testid="person-overdue-total">{{ overdueTotalOf(p) }}</td>
              <td>
                <app-person-claims [personId]="p.id" [claims]="claimsByPerson().get(p.id) ?? []"
                  [rates]="rates()" [floor]="floor()" [grade]="p.grade" [periods]="periods()"
                  [terms]="terms()" [today]="session.today()"
                  (saved)="claimSaved($event)" />
              </td>
              <td>
                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="open(p)"
                  [attr.aria-label]="'Edit ' + p.name">Edit</button>
                <button type="button" data-testid="person-statement" (click)="statement(p)"
                  [attr.aria-label]="'Take a statement of ' + p.name">Statement</button>
                <label [for]="'person-retire-date-' + p.id" class="visually-hidden">Retire {{ p.name }} from</label>
                <input #retireDate type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date" />
                <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
                  [attr.aria-label]="'Retire ' + p.name">Retire</button>
                <button type="button" data-testid="person-hold-toggle" (click)="hold(p)"
                  [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name">{{ p.held ? 'Release' : 'Hold' }}</button>
                @if (personError()?.id === p.id) {
                  <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class PeopleList {
  protected readonly session = inject(Session);
  private readonly api = inject(People);
  private readonly claimsApi = inject(Claims);
  private readonly ratesApi = inject(Rates);
  private readonly periodsApi = inject(Periods);
  private readonly settingsApi = inject(SheetSettings);

  protected readonly grades: Grade[] = ['A', 'B', 'C'];
  protected readonly people = signal<Person[]>([]);
  /** Whether retired people are listed; off when the screen opens, kept as it is across loads. */
  protected readonly showRetired = signal(false);
  /** The people listed: everyone, or only those not retired unless "show retired" is on. */
  protected readonly shown = computed(() =>
    this.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
  );
  /** Every claim on the sheet, newest first. */
  protected readonly claims = signal<Claim[]>([]);
  protected readonly claimsByPerson = computed(() => {
    const by = new Map<number, Claim[]>();
    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
    return by;
  });
  /** The people on hold, by id. */
  private readonly held = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
  /** The claims that count in the live totals, newest first. */
  private readonly live = computed(() => this.claims().filter((c) => countsLive(c, this.held().has(c.personId))));
  /** What each person has claimed: the sum of their open and settled claims' amounts, leaving out
   *  the open ones while they are on hold. */
  protected readonly claimed = computed(() => {
    const by = new Map<number, string>();
    for (const [id, cs] of this.claimsByPerson()) {
      by.set(id, sumAmounts(cs.filter((c) => countsLive(c, this.held().has(id))).map((c) => c.amount)));
    }
    return by;
  });
  protected readonly claimedTotal = computed(() => sumAmounts(this.live().map((c) => c.amount)));
  /** The rates set on the sheet. */
  protected readonly rates = signal<Rate[]>([]);
  /** The sheet's floor: the least live due a claim has. */
  protected readonly floor = signal('1.00');
  /** The sheet's terms: the days after its date a claim is due by. */
  protected readonly terms = signal(14);
  /** The periods on the sheet, earliest first. */
  protected readonly periods = signal<Period[]>([]);
  /** Each period's due-total by its id: the due figures of the claims that count whose date falls
   *  in it, skipping those with no due. */
  protected readonly periodDueTotals = computed(() => {
    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
    const figures = new Map<number, string[]>(this.periods().map((p) => [p.id, []]));
    for (const c of this.live()) {
      const period = periodOf(this.periods(), c.date);
      const grade = grades.get(c.personId);
      if (period === undefined || grade === undefined) continue;
      const d = claimDue(c, this.rates(), grade, this.floor());
      if (d !== null) figures.get(period.id)?.push(d);
    }
    const by = new Map<number, string>();
    for (const [id, ds] of figures) by.set(id, sumAmounts(ds));
    return by;
  });
  /** Each grade's rate in force on the sheet's today; a grade with none is missing. */
  protected readonly pctOf = computed(() => {
    const today = this.session.today();
    const by = new Map<Grade, string>();
    if (today === null) return by;
    for (const g of this.grades) {
      const pct = pctOn(this.rates(), g, today);
      if (pct !== undefined) by.set(g, pct);
    }
    return by;
  });
  /** The sheet's due-total: everyone's due-total added up, skipping those that are n/a. */
  protected readonly dueTotal = computed(() =>
    sumAmounts(this.people().map((p) => this.dueOf(p)).filter((d): d is string => d !== null)),
  );
  /** How many claims on the sheet are overdue among those that count in the live totals. */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
  );
  /** The sheet's overdue-total: the due figures of the overdue claims that count, skipping those
   *  with no due. */
  protected readonly overdueTotal = computed(() =>
    sumAmounts(this.people().map((p) => this.overdueTotalOf(p))),
  );
  /** The id of the person whose editor is open, or null when the form adds a person. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person the open editor loaded. */
  private version = 0;
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly error = signal('');
  /** The refusal of the last action taken on a person's row, shown on that row. */
  protected readonly personError = signal<{ id: number; message: string } | null>(null);
  /** The people whose statement is waiting for its answer: a second press meanwhile is ignored. */
  private readonly stating = new Set<number>();
  /** The people whose hold is waiting for its answer: a second press meanwhile is ignored. */
  private readonly holding = new Set<number>();
  /** The people whose retirement is waiting for its answer: a second press meanwhile is ignored. */
  private readonly retiring = new Set<number>();
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    grade: new FormControl<Grade>('A', { nonNullable: true }),
  });
  /** Only the newest read of the sheet may show: a load overtaken by another is dropped. */
  private reads = 0;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      const sheetId = this.session.sheetId();
      this.session.loads();
      this.people.set([]);
      this.claims.set([]);
      this.rates.set([]);
      this.periods.set([]);
      this.personError.set(null);
      this.reset();
      if (sheetId) void this.reload(sheetId);
    });
  }

  protected open(p: Person): void {
    this.personError.set(null);
    this.editing.set(p.id);
    this.version = p.version;
    this.form.setValue({ name: p.name, grade: p.grade });
    this.error.set('');
  }

  /** Take a statement of the person, then show them and their claims as it left them. */
  protected async statement(p: Person): Promise<void> {
    if (this.stating.has(p.id)) return;
    this.stating.add(p.id);
    this.personError.set(null);
    try {
      const taken = await this.api.statement(p.id);
      this.people.update((ps) => ps.map((x) => (x.id === taken.person.id ? taken.person : x)));
      const byId = new Map(taken.claims.map((c) => [c.id, c]));
      this.claims.update((cs) => [...cs.filter((c) => !byId.has(c.id)), ...taken.claims].sort((a, b) => b.id - a.id));
    } catch {
      this.personError.set({ id: p.id, message: 'The statement could not be taken.' });
    } finally {
      this.stating.delete(p.id);
    }
  }

  /** Retire the person from the day given, or the sheet's today when it is left blank. */
  protected async retire(p: Person, from: string): Promise<void> {
    if (this.retiring.has(p.id)) return;
    this.retiring.add(p.id);
    this.personError.set(null);
    try {
      const saved = await this.api.retire(p.id, from.trim() || null);
      this.people.update((ps) => ps.map((x) => (x.id === saved.id ? saved : x)));
      if (this.editing() === saved.id) this.version = saved.version;
    } catch {
      this.personError.set({ id: p.id, message: 'The person could not be retired.' });
    } finally {
      this.retiring.delete(p.id);
    }
  }

  /** Put the person on hold, or take them off it when they are on hold. */
  protected async hold(p: Person): Promise<void> {
    if (this.holding.has(p.id)) return;
    this.holding.add(p.id);
    this.personError.set(null);
    try {
      const saved = await this.api.hold(p.id, !p.held);
      this.people.update((ps) => ps.map((x) => (x.id === saved.id ? saved : x)));
      if (this.editing() === saved.id) this.version = saved.version;
    } catch {
      this.personError.set({ id: p.id, message: p.held ? 'The person could not be released.' : 'The person could not be put on hold.' });
    } finally {
      this.holding.delete(p.id);
    }
  }

  protected cancel(): void {
    this.reset();
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { name, grade } = this.form.getRawValue();
    if (!name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    if (!this.grades.includes(grade)) {
      this.error.set('Choose a grade of A, B or C.');
      return;
    }
    const id = this.editing();
    this.submitting = true;
    try {
      if (id === null) {
        const added = await this.api.add({ name, grade });
        this.people.update((ps) => [...ps, added]);
      } else {
        const saved = await this.api.edit(id, this.version, { name, grade });
        this.people.update((ps) => ps.map((p) => (p.id === saved.id ? saved : p)));
      }
      this.reset();
    } catch (e) {
      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
        await this.showCurrent(id);
        this.error.set('Someone else saved this person in the meantime. The form now shows their current values.');
      } else if (e instanceof HttpErrorResponse && e.status === 409) {
        this.error.set('That name is already in use on this sheet.');
      } else {
        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
      }
    } finally {
      this.submitting = false;
    }
  }

  /** Re-read the person whose save was overtaken and show them as they are now, in their row and in
   *  the still-open editor, which then saves over that version. */
  private async showCurrent(id: number): Promise<void> {
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const current = (await this.api.list(sheetId)).find((p) => p.id === id);
      if (!current || this.editing() !== id) return;
      this.people.update((ps) => ps.map((p) => (p.id === id ? current : p)));
      this.version = current.version;
      this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
    } catch {
      // the editor keeps what was typed; reopening it reads the person again
    }
  }

  protected claimSaved(claim: Claim): void {
    this.claims.update((cs) =>
      cs.some((c) => c.id === claim.id)
        ? cs.map((c) => (c.id === claim.id ? claim : c))
        : [claim, ...cs].sort((a, b) => b.id - a.id),
    );
  }

  protected quickAdded({ person, claim }: QuickAdded): void {
    this.people.update((ps) =>
      ps.some((p) => p.id === person.id) ? ps.map((p) => (p.id === person.id ? person : p)) : [...ps, person],
    );
    this.claimSaved(claim);
  }

  protected rateSaved(rate: Rate): void {
    const key = (r: Rate) => r.grade + (r.from ?? '');
    this.rates.update((rs) =>
      [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate].sort((a, b) =>
        key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0,
      ),
    );
  }

  protected periodSaved(period: Period): void {
    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0)));
  }

  /** A person's due-total: the sum of the due figures of their open and settled claims, leaving out
   *  the open ones while they are on hold. Null (n/a)
   *  when their grade has no rate on the sheet's today and no settled or stated claim keeps a figure. */
  protected dueOf(p: Person): string | null {
    const counted = (this.claimsByPerson().get(p.id) ?? []).filter((c) => countsLive(c, p.held));
    if (!this.pctOf().has(p.grade) && !counted.some(fixed)) {
      return null;
    }
    const figures = counted.map((c) => claimDue(c, this.rates(), p.grade, this.floor())).filter((d): d is string => d !== null);
    return sumAmounts(figures);
  }

  /** A person's overdue claims among those that count in the live totals. */
  protected overdueOf(p: Person): Claim[] {
    return (this.claimsByPerson().get(p.id) ?? [])
      .filter((c) => countsLive(c, p.held) && overdue(c, this.terms(), this.session.today()));
  }

  /** A person's overdue-total: the due figures of their overdue claims that count, skipping those
   *  with no due. */
  protected overdueTotalOf(p: Person): string {
    return sumAmounts(this.overdueOf(p).map((c) => claimDue(c, this.rates(), p.grade, this.floor()))
      .filter((d): d is string => d !== null));
  }

  private reset(): void {
    this.editing.set(null);
    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
    this.error.set('');
  }

  private async reload(sheetId: string): Promise<void> {
    const read = ++this.reads;
    try {
      const [people, claims, rates, periods, settings] = await Promise.all([
        this.api.list(sheetId),
        this.claimsApi.list(sheetId),
        this.ratesApi.list(sheetId),
        this.periodsApi.list(sheetId),
        this.settingsApi.get(sheetId),
      ]);
      if (read === this.reads) {
        this.rates.set(rates);
        this.floor.set(settings.floor);
        this.terms.set(settings.terms);
        this.periods.set(periods);
        this.claims.set(claims);
        this.people.set(people);
      }
    } catch {
      // the list stays empty; the next load reads it again
    }
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { AMOUNT, Claim, ClaimAction, Claims, claimDue, dueBy, overdue } from '../../core/claims';
import { Grade } from '../../core/people';
import { Period, periodOf } from '../../core/periods';
import { Rate } from '../../core/rates';

/** Why the server refused an action: the claim's status does not allow it. */
const REFUSALS: Record<ClaimAction, string> = {
  open: 'Only a draft claim can be opened.',
  settle: 'Only an open claim can be settled.',
  void: 'Only a draft or open claim can be voided.',
};

/** The message when an edit of a claim that is not a draft is refused. */
const NOT_DRAFT = 'Only a draft claim can be edited; void an open claim and add a new one.';

/** The message when the server refused a change to a claim dated inside a closed period. */
const CLOSED = 'The claim\'s period is closed.';
const RETIRED = 'A claim cannot be dated after the person\'s retirement.';

/** The message for a refused action on a claim. */
function refusal(e: unknown, action: ClaimAction): string {
  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
  if (e instanceof HttpErrorResponse && e.status === 409) return REFUSALS[action];
  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'settle') {
    return 'The user who opened a claim cannot settle it.';
  }
  if (e instanceof HttpErrorResponse && e.status === 422 && action === 'settle') {
    return 'A clerk cannot settle a claim whose due is above the clerk limit.';
  }
  return 'The claim could not be changed.';
}

// A person's claims, newest first, and the form that adds a claim for them or, once a claim's
// editor is opened, edits it.
@Component({
  selector: 'app-person-claims',
  imports: [ReactiveFormsModule],
  template: `
    <form data-testid="claim-form" [formGroup]="form" (ngSubmit)="submit()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input [id]="'claim-form-amount-' + personId()" data-testid="claim-form-amount" formControlName="amount"
        inputmode="decimal" />
      <label [for]="'claim-form-date-' + personId()">Date</label>
      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
      <button type="submit" data-testid="claim-form-submit">{{ editing() === null ? 'Add claim' : 'Save claim' }}</button>
      @if (error()) {
        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
      }
    </form>
    <ul data-testid="claims">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <span data-testid="claim-number">{{ c.number ?? '' }}</span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span data-testid="claim-due">{{ dueOf(c) }}</span>
          <span data-testid="claim-status">{{ c.status }}</span>
          <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span>
          <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span>
          <span data-testid="claim-period">{{ periodName(c) }}</span>
          <span data-testid="claim-due-by">{{ dueByOf(c) }}</span>
          <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span>
          <button type="button" data-testid="claim-open" (click)="act(c, 'open')"
            [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
          <button type="button" data-testid="claim-settle" (click)="act(c, 'settle')"
            [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
          <button type="button" data-testid="claim-void" (click)="act(c, 'void')"
            [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
          <button type="button" data-testid="claim-edit" (click)="open(c)"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          @if (editing() === c.id) {
            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
          }
          @if (claimError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly api = inject(Claims);

  readonly personId = input.required<number>();
  /** This person's claims, newest first. */
  readonly claims = input.required<Claim[]>();
  /** The rates set on the sheet; a claim's due uses its person's grade's rate on the claim's date. */
  readonly rates = input.required<Rate[]>();
  /** The sheet's floor: the least live due a claim has. */
  readonly floor = input.required<string>();
  readonly grade = input.required<Grade>();
  /** The periods on the sheet; a claim belongs to the one whose days contain its date. */
  readonly periods = input.required<Period[]>();
  /** The sheet's terms: the days after its date a claim is due by. */
  readonly terms = input.required<number>();
  /** The sheet's today; a claim is overdue once its due-by is before it. */
  readonly today = input.required<string | null>();
  /** A claim added or saved through the form. */
  readonly saved = output<Claim>();

  /** The id of the claim whose editor is open, or null when the form adds a claim. */
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal('');
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  /** The refusal of the last action taken on a claim's row, shown on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected dueOf(c: Claim): string {
    return claimDue(c, this.rates(), this.grade(), this.floor()) ?? 'n/a';
  }

  protected dueByOf(c: Claim): string {
    return dueBy(c, this.terms());
  }

  protected overdueOf(c: Claim): boolean {
    return overdue(c, this.terms(), this.today());
  }

  /** The name of the period the claim belongs to; empty when it belongs to none. */
  protected periodName(c: Claim): string {
    return periodOf(this.periods(), c.date)?.name ?? '';
  }

  protected open(c: Claim): void {
    this.claimError.set(null);
    if (c.status !== 'DRAFT') {
      this.claimError.set({ id: c.id, message: NOT_DRAFT });
      return;
    }
    this.editing.set(c.id);
    this.form.setValue({ amount: c.amount, date: c.date, note: c.note }, { emitEvent: false });
    this.error.set('');
  }

  protected async act(c: Claim, action: ClaimAction): Promise<void> {
    this.claimError.set(null);
    try {
      this.saved.emit(await this.api.act(c.id, action));
    } catch (e) {
      this.claimError.set({
        id: c.id,
        message: refusal(e, action),
      });
    }
  }

  protected cancel(): void {
    this.reset();
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    this.claimError.set(null);
    const { amount, date, note } = this.form.getRawValue();
    if (!AMOUNT.test(amount.trim())) {
      this.error.set('Enter an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const day = date.trim();
    if (day !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      this.error.set('Enter a date, or leave it blank for the sheet\'s today.');
      return;
    }
    const form = { amount: amount.trim(), date: day === '' ? null : day, note };
    const id = this.editing();
    this.submitting = true;
    try {
      const claim = id === null ? await this.api.add(this.personId(), form) : await this.api.edit(id, form);
      this.saved.emit(claim);
      this.reset();
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 423) this.error.set(CLOSED);
      else if (e instanceof HttpErrorResponse && e.status === 422) this.error.set(RETIRED);
      else if (id !== null && e instanceof HttpErrorResponse && e.status === 409) {
        this.claimError.set({ id, message: NOT_DRAFT });
      }
      else this.error.set(id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
    } finally {
      this.submitting = false;
    }
  }

  private reset(): void {
    this.editing.set(null);
    this.form.reset({ amount: '', date: '', note: '' }, { emitEvent: false });
    this.error.set('');
  }
}

