-- The days after its date a claim is due by; a sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- The least live due a claim on the sheet has; a sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
-- The rate for each grade on a sheet: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0),
    CONSTRAINT rate_sheet_grade_unique UNIQUE (sheet_id, grade)
);

    /** A period's due-total: the due figures of the claims that count whose date falls in it,
     *  skipping those with no due and the open claims of people on hold. */
    private BigDecimal dueTotal(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || !Dues.countsLive(person, c) || c.getDate().isBefore(period.getFromDate())
                    || c.getDate().isAfter(period.getToDate())) {
                continue;
            }
            BigDecimal figure = dues.figure(sheetId, person, c);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        return total;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
    }
}

